<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { classroomApi, type ApiError } from '../../app/api'
import YkCheck from '../../components/common/YkCheck.vue'
import YkTabs from '../../components/common/YkTabs.vue'
type Item={artifact_id?:string;event_id?:string;event_type?:string;name?:string;student_id?:string;occurred_at?:string;action?:string;size_bytes?:number;detail?:Record<string,unknown>}
type Student={student_id:string;student_name:string;student_no?:string}
const tab=ref('audit'), items=ref<Item[]>([]), students=ref<Student[]>([]), selectedTargets=ref<string[]>([]), error=ref(''), history=ref<any[]>([]), title=ref('网络流量分析'), instruction=ref('下载日志并定位异常连接'), count=ref(1), dueAt=ref(''), message=ref(''), selectedLog=ref<Item|null>(null), loading=ref(true)
const courseId=localStorage.getItem('yk-course-id')||'course-a', classId=localStorage.getItem('yk-class-id')||'class-a', releaseId=localStorage.getItem('yk-release-id')||'release-1'
const scopeQuery=computed(()=>`class_id=${encodeURIComponent(classId)}&lab_release_id=${encodeURIComponent(releaseId)}`)
function targetChecked(studentId:string){return selectedTargets.value.includes(studentId)}
function setTarget(studentId:string,checked:boolean){selectedTargets.value=checked?[...selectedTargets.value,studentId]:selectedTargets.value.filter(id=>id!==studentId)}
async function load(){loading.value=true;error.value='';try{const path=tab.value==='audit'?'/api/v1/teaching-logs/audit':'/api/v1/teaching-logs/traffic';const [logs,distributions,roster]=await Promise.all([classroomApi<{items:Item[]}>(`${path}?${scopeQuery.value}`),classroomApi<{items:any[]}>('/api/v1/teaching-logs/distributions'),classroomApi<{items:Student[]}>(`/api/v1/classroom/lab-releases/${releaseId}/students`)]);items.value=logs.items;history.value=distributions.items;students.value=roster.items}catch(e){error.value=(e as ApiError).message}finally{loading.value=false}}
async function download(id?:string){if(!id||tab.value!=='traffic')return;try{const r=await classroomApi<{download_url:string}>(`/api/v1/teaching-logs/traffic/${id}/download`);window.open(r.download_url,'_blank','noopener')}catch(e){error.value=(e as ApiError).message}}
async function distribute(){message.value='';error.value='';if(!selectedTargets.value.length){error.value='请至少选择一名本班学生';return}try{await classroomApi('/api/v1/teaching-logs/distributions','teacher',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({course_id:courseId,class_id:classId,lab_release_id:releaseId,distribution_type:tab.value==='audit'?'AUDIT':'TRAFFIC',source_filter:{},requested_count:count.value,target_student_ids:selectedTargets.value,title:title.value,instruction:instruction.value,due_at:dueAt.value||null})});message.value=`日志任务已分发给 ${selectedTargets.value.length} 名学生`;await load()}catch(e){error.value=(e as ApiError).message}}
onMounted(load)
</script>
<template><div class="stack"><header class="page-header"><div><h1>教学日志</h1><p>查阅审计与流量日志，并向本班学生分发训练材料。</p></div><button class="yk-button" @click="load">刷新</button></header><YkTabs v-model="tab" :tabs="[{label:'审计日志',value:'audit'},{label:'流量日志',value:'traffic'}]" @update:model-value="load"/><div v-if="error" class="pending-panel" role="alert">{{error}}</div><div v-if="loading" class="card">正在加载日志与班级名单…</div><section v-else class="grid grid-2"><div class="card"><h3>日志清单</h3><div class="scroll"><table class="data-table"><thead><tr><th>时间</th><th>日志</th><th>学生</th><th>大小</th><th>操作</th></tr></thead><tbody><tr v-for="(item,index) in items" :key="item.artifact_id||item.event_id||index"><td>{{item.occurred_at||'—'}}</td><td>{{item.name||item.action||item.event_type||'审计事件'}}</td><td>{{item.student_id||'系统'}}</td><td>{{item.size_bytes==null?'—':`${item.size_bytes} 字节`}}</td><td class="actions"><button class="yk-button" type="button" @click="selectedLog=item">查看</button><button v-if="item.artifact_id&&tab==='traffic'" class="yk-button" type="button" @click="download(item.artifact_id)">下载</button><span v-else class="muted">审计日志随任务分发</span></td></tr><tr v-if="!items.length"><td colspan="5" class="muted">暂无日志，或数据源待接入</td></tr></tbody></table></div><div v-if="selectedLog" class="pending-panel"><b>日志详情</b><p>时间：{{selectedLog.occurred_at||'—'}}</p><p>学生：{{selectedLog.student_id||'系统'}}</p><p>事件：{{selectedLog.event_type||selectedLog.name||selectedLog.action||'审计事件'}}</p><pre v-if="selectedLog.detail">{{JSON.stringify(selectedLog.detail,null,2)}}</pre><button class="yk-button" type="button" @click="selectedLog=null">关闭详情</button></div></div><form class="card form-grid" @submit.prevent="distribute"><h3>分发日志任务</h3><label>任务名称<input v-model="title" required maxlength="160"></label><label>任务要求<textarea v-model="instruction" required maxlength="4000"></textarea></label><fieldset><legend>目标学生（已选 {{selectedTargets.length}} 人）</legend><div class="scroll" style="max-height:210px"><div v-for="student in students" :key="student.student_id"><YkCheck :model-value="targetChecked(student.student_id)" :label="`${student.student_name} ${student.student_no||student.student_id}`" @update:model-value="setTarget(student.student_id,$event)"/></div></div></fieldset><label>日志数量<input v-model.number="count" type="number" min="1" :max="Math.max(items.length,1)"></label><label>截止时间（可选）<input v-model="dueAt" type="datetime-local"></label><button class="yk-button primary" :disabled="!items.length||!selectedTargets.length">确认分发</button><p v-if="message" class="status done">{{message}}</p></form></section><section class="card"><h3>分发记录</h3><p v-if="!history.length" class="muted">暂无分发记录</p><table v-else class="data-table"><thead><tr><th>任务名称</th><th>类型</th><th>状态</th><th>创建时间</th></tr></thead><tbody><tr v-for="item in history" :key="item.distribution_id"><td>{{item.title}}</td><td>{{item.distribution_type==='TRAFFIC'?'流量日志':'审计日志'}}</td><td>{{item.status==='ASSIGNED'?'已分发':'处理中'}}</td><td>{{item.created_at}}</td></tr></tbody></table></section></div></template>
